package vn.offline.sokhachcuoi.v2;

import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.graphics.Typeface;import android.net.Uri;import android.provider.Settings;import android.speech.RecognizerIntent;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.text.NumberFormat;import java.util.*;

public class MainActivity extends Activity{
    final int BURG=Color.rgb(139,30,63), GOLD=Color.rgb(184,134,11), IVORY=Color.rgb(255,248,240), TEXT=Color.rgb(55,42,42); DbHelper db; LinearLayout body; EditText voiceTarget; final int VOICE=77, BACKUP=88, RESTORE=89, XLSX_IMPORT=90, XLSX_EXPORT=91, XLSX_TEMPLATE=92;
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} TextView tv(String s,int sp,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(TEXT);v.setPadding(dp(4),dp(4),dp(4),dp(4));if(bold)v.setTypeface(null,Typeface.BOLD);return v;}
    Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setAllCaps(false);GradientDrawableBg.apply(b,BURG,16);b.setElevation(0);return b;}
    void margins(View v,int l,int t,int r,int b){ViewGroup.LayoutParams raw=v.getLayoutParams();if(raw instanceof ViewGroup.MarginLayoutParams){ViewGroup.MarginLayoutParams p=(ViewGroup.MarginLayoutParams)raw;p.setMargins(dp(l),dp(t),dp(r),dp(b));v.setLayoutParams(p);}}
    @Override public void onCreate(Bundle b){super.onCreate(b);db=new DbHelper(this);showDashboard();}
    void shell(String title){
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(IVORY);
        TextView h=tv("💍  "+title,26,true);h.setTextColor(BURG);h.setPadding(dp(18),dp(16),dp(18),dp(8));root.addView(h);
        ScrollView sv=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(14),dp(2),dp(14),dp(18));sv.addView(body);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout navWrap=new LinearLayout(this);navWrap.setPadding(dp(8),dp(6),dp(8),dp(8));navWrap.setGravity(Gravity.CENTER);
        String[] ns={"Tổng quan","Khách mời","Nhóm khách","Cài đặt"};String[] icons={"⌂","♟","◉","⚙"};
        for(int i=0;i<ns.length;i++){final String n=ns[i];Button x=new Button(this);x.setText(icons[i]+"  "+n);x.setTextSize(10);x.setAllCaps(false);boolean active=(title.equals("SỔ KHÁCH CƯỚI")&&n.equals("Tổng quan"))||(title.equals("DANH SÁCH KHÁCH MỜI")&&n.equals("Khách mời"))||(title.equals("NHÓM KHÁCH")&&n.equals("Nhóm khách"))||(title.equals("CÀI ĐẶT & SAO LƯU")&&n.equals("Cài đặt"));x.setTextColor(active?Color.WHITE:TEXT);GradientDrawableBg.apply(x,active?BURG:Color.WHITE,16);x.setElevation(0);x.setOnClickListener(v->{if(n.equals("Tổng quan"))showDashboard();if(n.equals("Khách mời"))showGuests();if(n.equals("Nhóm khách"))showGroups();if(n.equals("Cài đặt"))showSettings();});LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,dp(52),1);np.setMargins(dp(3),0,dp(3),0);navWrap.addView(x,np);}
        root.addView(navWrap);setContentView(root);
    }
    LinearLayout compactCard(String title,String value){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(13),dp(9),dp(13),dp(9));GradientDrawableBg.apply(c,Color.WHITE,16);TextView a=tv(title,12,false),b=tv(value,22,true);b.setTextColor(BURG);c.addView(a);c.addView(b);return c;}
    void card(String title,String value){LinearLayout c=compactCard(title,value);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));body.addView(c,p);}
    void showDashboard(){
        shell("SỔ KHÁCH CƯỚI");
        ImageView logo=new ImageView(this);logo.setImageResource(vn.offline.sokhachcuoi.v2.R.drawable.app_logo);logo.setScaleType(ImageView.ScaleType.CENTER_CROP);body.addView(logo,new LinearLayout.LayoutParams(-1,dp(118)));
        TextView sub=tv("Quản lý khách mời • Hoàn toàn offline",13,false);body.addView(sub);
        Button add=btn("＋  THÊM KHÁCH MỜI");add.setTextSize(15);add.setOnClickListener(v->guestDialog(null));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(52));ap.setMargins(0,dp(8),0,dp(10));body.addView(add,ap);
        LinearLayout row1=new LinearLayout(this),row2=new LinearLayout(this);
        LinearLayout c1=compactCard("Tổng khách",String.valueOf(db.count(null))),c2=compactCard("Đã mời điện thoại",String.valueOf(db.count("called=1"))),c3=compactCard("Đã gửi thiệp",String.valueOf(db.count("invited=1"))),c4=compactCard("Chưa gửi thiệp",String.valueOf(db.count("invited=0")));
        LinearLayout.LayoutParams cp1=new LinearLayout.LayoutParams(0,-2,1);cp1.setMargins(0,dp(4),dp(4),dp(4));LinearLayout.LayoutParams cp2=new LinearLayout.LayoutParams(0,-2,1);cp2.setMargins(dp(4),dp(4),0,dp(4));row1.addView(c1,cp1);row1.addView(c2,cp2);row2.addView(c3,new LinearLayout.LayoutParams(cp1));row2.addView(c4,new LinearLayout.LayoutParams(cp2));body.addView(row1);body.addView(row2);
        card("Tổng tiền mừng",money(db.giftTotal()));
    }
    String money(long n){return NumberFormat.getNumberInstance(new Locale("vi","VN")).format(n)+" ₫";}
    void showGuests(){shell("DANH SÁCH KHÁCH MỜI");EditText q=new EditText(this);q.setHint("🔎 Tìm theo họ tên hoặc SĐT");body.addView(q);LinearLayout filters=new LinearLayout(this);Spinner gp=new Spinner(this),st=new Spinner(this);ArrayList<String> gl=db.groups();gl.add(0,"Tất cả nhóm");gp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,gl));String[] states={"Tất cả trạng thái","Chưa mời ĐT","Đã mời ĐT","Chưa gửi thiệp","Đã gửi thiệp"};st.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,states));filters.addView(gp,new LinearLayout.LayoutParams(0,-2,1));filters.addView(st,new LinearLayout.LayoutParams(0,-2,1));body.addView(filters);Button apply=btn("Lọc danh sách");body.addView(apply);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);Runnable load=()->loadGuests(list,q.getText().toString(),(String)gp.getSelectedItem(),(String)st.getSelectedItem());apply.setOnClickListener(v->load.run());q.setOnEditorActionListener((v,a,e)->{load.run();return true;});load.run();Button add=btn("＋ Thêm khách");add.setOnClickListener(v->guestDialog(null));body.addView(add);}
    void loadGuests(LinearLayout list,String q,String g,String state){list.removeAllViews();Cursor c=db.guests(q,g,state);int stt=0;while(c.moveToNext()){stt++;long id=c.getLong(c.getColumnIndexOrThrow("id"));String name=c.getString(c.getColumnIndexOrThrow("name")),group=c.getString(c.getColumnIndexOrThrow("group_name")),phone=c.getString(c.getColumnIndexOrThrow("phone"));boolean called=c.getInt(c.getColumnIndexOrThrow("called"))==1,inv=c.getInt(c.getColumnIndexOrThrow("invited"))==1;Long gift=c.isNull(c.getColumnIndexOrThrow("gift"))?null:c.getLong(c.getColumnIndexOrThrow("gift"));LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),dp(10),dp(14),dp(10));GradientDrawableBg.apply(box,Color.WHITE,16);TextView n=tv(stt+".  "+name,18,true);n.setTextColor(BURG);box.addView(n);box.addView(tv("💐 "+group+(phone.isEmpty()?"":"    ☎ "+phone),13,false));LinearLayout checks=new LinearLayout(this);CheckBox cb1=new CheckBox(this);cb1.setText("Đã mời ĐT");cb1.setChecked(called);CheckBox cb2=new CheckBox(this);cb2.setText("Đã gửi thiệp");cb2.setChecked(inv);checks.addView(cb1,new LinearLayout.LayoutParams(0,-2,1));checks.addView(cb2,new LinearLayout.LayoutParams(0,-2,1));box.addView(checks);if(gift!=null){TextView m=tv("🎁 Tiền mừng: "+money(gift),14,true);m.setTextColor(GOLD);box.addView(m);}cb1.setOnCheckedChangeListener((b,x)->db.toggle(id,"called",x));cb2.setOnCheckedChangeListener((b,x)->db.toggle(id,"invited",x));box.setOnClickListener(v->editById(id));box.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle("Xóa khách mời?").setMessage(name).setNegativeButton("Hủy",null).setPositiveButton("Xóa",(d,w)->{db.deleteGuest(id);showGuests();}).show();return true;});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(6));list.addView(box,p);}c.close();if(stt==0)list.addView(tv("Chưa có khách phù hợp bộ lọc.",15,false));}
    void editById(long id){Cursor c=db.getReadableDatabase().rawQuery("SELECT * FROM guests WHERE id=?",new String[]{String.valueOf(id)});if(c.moveToFirst()){HashMap<String,Object> m=new HashMap<>();m.put("id",id);m.put("name",c.getString(c.getColumnIndexOrThrow("name")));m.put("group",c.getString(c.getColumnIndexOrThrow("group_name")));m.put("phone",c.getString(c.getColumnIndexOrThrow("phone")));m.put("called",c.getInt(c.getColumnIndexOrThrow("called"))==1);m.put("invited",c.getInt(c.getColumnIndexOrThrow("invited"))==1);m.put("gift",c.isNull(c.getColumnIndexOrThrow("gift"))?"":String.valueOf(c.getLong(c.getColumnIndexOrThrow("gift"))));guestDialog(m);}c.close();}
    void guestDialog(HashMap<String,Object> old){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(18),0,dp(18),0);EditText name=new EditText(this);name.setHint("Họ và tên");Button mic=btn("🎤 Nhập họ tên bằng giọng nói");mic.setOnClickListener(v->startVoice(name));Spinner group=new Spinner(this);group.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.groups()));EditText phone=new EditText(this);phone.setHint("Số điện thoại");phone.setInputType(3);CheckBox called=new CheckBox(this);called.setText("Đã mời qua điện thoại");CheckBox invited=new CheckBox(this);invited.setText("Đã gửi thiệp");EditText gift=new EditText(this);gift.setHint("Tiền mừng (để trống nếu chưa có)");gift.setInputType(2);f.addView(name);f.addView(mic);f.addView(tv("Nhóm khách",13,true));f.addView(group);f.addView(phone);f.addView(called);f.addView(invited);f.addView(gift);Long id=null;if(old!=null){id=(Long)old.get("id");name.setText((String)old.get("name"));phone.setText((String)old.get("phone"));
phone.setOnClickListener(v->{
    String number=phone.getText().toString().trim();
    if(!number.isEmpty()){
        Intent intent=new Intent(Intent.ACTION_DIAL);
        intent.setData(android.net.Uri.parse("tel:"+number));
        startActivity(intent);
    }
});called.setChecked((Boolean)old.get("called"));invited.setChecked((Boolean)old.get("invited"));gift.setText((String)old.get("gift"));int pos=db.groups().indexOf((String)old.get("group"));if(pos>=0)group.setSelection(pos);}final Long fid=id;new AlertDialog.Builder(this).setTitle(old==null?"Thêm khách mời":"Sửa khách mời").setView(f).setNegativeButton("Hủy",null).setPositiveButton("Lưu",null).setOnDismissListener(d->{}).create().setOnShowListener(x->{});AlertDialog dlg=new AlertDialog.Builder(this).setTitle(old==null?"Thêm khách mời":"Sửa khách mời").setView(f).setNegativeButton("Hủy",null).setPositiveButton("Lưu",null).create();dlg.setOnShowListener(x->dlg.getButton(-1).setOnClickListener(v->{if(name.getText().toString().trim().isEmpty()){name.setError("Nhập họ tên");return;}Long gm=null;String s=gift.getText().toString().replaceAll("[^0-9]","");if(!s.isEmpty())try{gm=Long.parseLong(s);}catch(Exception ignored){}db.saveGuest(fid,name.getText().toString(),String.valueOf(group.getSelectedItem()),phone.getText().toString(),called.isChecked(),invited.isChecked(),gm);dlg.dismiss();showGuests();}));dlg.show();}
    void startVoice(EditText target){voiceTarget=target;Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"vi-VN");i.putExtra(RecognizerIntent.EXTRA_PROMPT,"Mời anh nói nội dung...");try{startActivityForResult(i,VOICE);}catch(Exception e){Toast.makeText(this,"Điện thoại chưa có dịch vụ nhận dạng giọng nói.",Toast.LENGTH_LONG).show();}}
    void showGroups(){shell("NHÓM KHÁCH");EditText n=new EditText(this);n.setHint("Tên nhóm mới");body.addView(n);Button mic=btn("🎤 Nói tên nhóm");mic.setOnClickListener(v->startVoice(n));body.addView(mic);Button add=btn("＋ Thêm nhóm");add.setOnClickListener(v->{db.addGroup(n.getText().toString());showGroups();});body.addView(add);for(String g:db.groups()){LinearLayout r=new LinearLayout(this);TextView t=tv("💐 "+g,17,true);r.addView(t,new LinearLayout.LayoutParams(0,dp(54),1));Button del=new Button(this);del.setText("Xóa");del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Xóa nhóm?").setMessage("Khách cũ vẫn giữ tên nhóm này.").setNegativeButton("Hủy",null).setPositiveButton("Xóa",(d,w)->{db.deleteGroup(g);showGroups();}).show());r.addView(del);body.addView(r);}}
    void showSettings(){shell("CÀI ĐẶT & EXCEL");body.addView(tv("SỔ KHÁCH CƯỚI V2.0 • Dữ liệu lưu độc lập trên điện thoại • Không khai báo quyền INTERNET.",15,false));Button xi=btn("📥 Import danh sách Excel (.xlsx)");xi.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");startActivityForResult(i,XLSX_IMPORT);});body.addView(xi);Button xo=btn("📤 Xuất danh sách Excel (.xlsx)");xo.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");i.putExtra(Intent.EXTRA_TITLE,"danh_sach_khach_moi.xlsx");startActivityForResult(i,XLSX_EXPORT);});body.addView(xo);Button xt=btn("📄 Tạo file Excel mẫu");xt.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");i.putExtra(Intent.EXTRA_TITLE,"mau_import_khach_moi.xlsx");startActivityForResult(i,XLSX_TEMPLATE);});body.addView(xt);body.addView(tv("Cột Excel: STT • Họ tên • SĐT • Nhóm khách • Đã mời điện thoại • Đã gửi thiệp • Số người đi • Tiền mừng • Ghi chú",13,false));Button b=btn("⬆ Sao lưu dữ liệu");b.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"so_khach_cuoi_backup.json");startActivityForResult(i,BACKUP);});body.addView(b);Button r=btn("⬇ Khôi phục dữ liệu");r.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");startActivityForResult(i,RESTORE);});body.addView(r);body.addView(tv("Lưu ý: Khôi phục sẽ thay thế danh sách hiện tại. Hãy giữ file sao lưu ở nơi an toàn.",13,false));}
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null)return;try{if(req==VOICE){ArrayList<String>a=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty()&&voiceTarget!=null){String old=voiceTarget.getText().toString().trim();voiceTarget.setText(old.isEmpty()?a.get(0):old+" "+a.get(0));voiceTarget.setSelection(voiceTarget.length());}}else if(req==XLSX_IMPORT){try(InputStream in=getContentResolver().openInputStream(data.getData())){int n=XlsxHelper.importGuests(db,in);Toast.makeText(this,"Đã nhập "+n+" khách từ Excel.",Toast.LENGTH_LONG).show();showGuests();}}else if(req==XLSX_EXPORT){try(OutputStream o=getContentResolver().openOutputStream(data.getData())){XlsxHelper.exportGuests(db,o);}Toast.makeText(this,"Đã xuất Excel.",Toast.LENGTH_LONG).show();}else if(req==XLSX_TEMPLATE){try(OutputStream o=getContentResolver().openOutputStream(data.getData())){XlsxHelper.exportTemplate(o);}Toast.makeText(this,"Đã tạo file Excel mẫu.",Toast.LENGTH_LONG).show();}else if(req==BACKUP){try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(db.exportJson().toString(2).getBytes(StandardCharsets.UTF_8));}Toast.makeText(this,"Đã sao lưu.",Toast.LENGTH_LONG).show();}else if(req==RESTORE){ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=getContentResolver().openInputStream(data.getData())){byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)b.write(buf,0,n);}org.json.JSONObject root=new org.json.JSONObject(b.toString("UTF-8"));new AlertDialog.Builder(this).setTitle("Khôi phục dữ liệu?").setMessage("Danh sách hiện tại sẽ được thay thế.").setNegativeButton("Hủy",null).setPositiveButton("Khôi phục",(d,w)->{try{db.importJson(root);Toast.makeText(this,"Khôi phục thành công.",Toast.LENGTH_LONG).show();showDashboard();}catch(Exception e){Toast.makeText(this,"Không thể khôi phục: "+e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}}catch(Exception e){Toast.makeText(this,"Có lỗi: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
    static class GradientDrawableBg{static void apply(View v,int color,int radius){android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(color);g.setCornerRadius(radius*v.getResources().getDisplayMetrics().density);g.setStroke(1,Color.rgb(235,220,210));v.setBackground(g);v.setElevation(3*v.getResources().getDisplayMetrics().density);}}
}
